-- 0022: Perbaikan visual untuk 2 project dari 0021 setelah dicek user di 3D
-- Preview -- render pertama meleset jauh dari foto referensi:
--
--  Root cause utama: generateLayout() (packer treemap) TIDAK sadar arah
--  "depan" site -- ia menaruh ruang apa saja di sudut manapun, sementara
--  buildFacadeComposerTemplate() menaruh gate/portal/driveway di sisi
--  frontOrientation (selatan = y besar) secara terpisah. Akibatnya carport
--  di kedua project mendarat di BELAKANG (y kecil), bukan di depan tempat
--  portal/gate sebenarnya berada -- persis keluhan user "carport harusnya di
--  depan". Fix: mirror y lantai dasar supaya carport ada di sisi depan yang
--  sama dengan portal/gate/driveway (wall-side "s"/"n" pada opening tetap
--  benar karena itu relatif ke ruang, bukan absolut ke site).
--
--  proj-modern-tropis-1 ("Rumah Tropis Modern"): foto referensi TIDAK punya
--  pagar/gate sama sekali -- carport terbuka langsung dari jalan. Elemen
--  boundary_wall/sliding_gate/pedestrian_gate dari template dibuang total,
--  begitu juga canopy/portal_frame template (redundan -- ruang carport
--  sendiri sudah auto-render kanopi+kolom, lihat build-model.ts baris
--  ~810). Ditambah 1 opening pintu depan (generateLayout cuma auto-tambah
--  jendela, tidak pernah pintu) + 1 taman kecil dekat pintu masuk.
--
--  proj-urban-monokrom-1 ("Rumah Urban Monokrom"): roofType diganti dari
--  "pelana" ke "datar" -- gable sejati (prisma segitiga penuh, lihat
--  roof-geometry-core.ts) dilihat dari depan (searah ridge) tampak seperti
--  piramida runcing, TIDAK seperti massa kotak flat-top gelap di foto.
--  Material dinding lantai 2 (kamar/ruang keluarga/balkon) diganti ke
--  "batu_alam_gelap" (facade-claddings.ts, #3b3f41) supaya lantai atas
--  benar-benar gelap seperti foto; lantai 1 tetap terang. Gate/pagar
--  dipertahankan (foto memang ada pagar besi rendah).
--
-- Payload adalah dump ulang dari generator app (generateLayout +
-- buildFacadeComposerTemplate + fix di atas, via vitest), bukan tulis
-- manual. Idempotent: upsert di-scope ke project_id yang sudah ada dari 0021
-- (guard `where exists`), aman di-replay.

insert into design_layouts (project_id, version_id, payload)
